import { prebuild, StrictModeError } from '@mintlify/prebuild';
import { checkBuild } from '../local-preview/check-build.js';
import { isOnline } from '../local-preview/is-online.js';
import { addLog } from '../logging-state.js';
vi.mock('@mintlify/prebuild', async (importOriginal) => {
    const mod = await importOriginal();
    return { ...mod, prebuild: vi.fn() };
});
vi.mock('../local-preview/is-online.js', () => ({ isOnline: vi.fn() }));
vi.mock('fs-extra', () => {
    const mocks = {
        ensureDir: vi.fn().mockResolvedValue(undefined),
        pathExists: vi.fn().mockResolvedValue(true),
        readFileSync: vi.fn().mockReturnValue('1.0.0'),
        emptyDirSync: vi.fn(),
    };
    return { ...mocks, default: mocks };
});
vi.mock('../local-preview/update.js', () => ({
    silentUpdateClient: vi.fn(async () => ({ needsUpdate: false, error: undefined })),
}));
vi.mock('../logging-state.js', async (importOriginal) => {
    const mod = await importOriginal();
    return { ...mod, addLog: vi.fn(), clearLogs: vi.fn() };
});
const argv = { _: [], $0: 'mint', packageName: 'mint' };
describe('checkBuild', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        vi.mocked(isOnline).mockResolvedValue(true);
        vi.spyOn(process, 'chdir').mockImplementation(() => undefined);
    });
    it('logs nothing', async () => {
        vi.mocked(prebuild).mockRejectedValue(new StrictModeError('Build validation failed with 1 warning(s). See above for details.'));
        const result = await checkBuild(argv);
        expect(result).toMatchObject({
            passed: false,
            error: expect.stringContaining('Build validation failed'),
            strict: true,
        });
        expect(addLog).not.toHaveBeenCalled();
    });
    it('passes when prebuild succeeds', async () => {
        vi.mocked(prebuild).mockResolvedValue(undefined);
        expect(await checkBuild(argv)).toEqual({ passed: true, warnings: [] });
    });
    it('returns a build failure instead of exiting', async () => {
        vi.mocked(prebuild).mockRejectedValue(new Error('boom'));
        expect(await checkBuild(argv)).toEqual({
            passed: false,
            error: 'boom',
            strict: false,
            warnings: [],
        });
    });
    it.each([
        ['passes', () => vi.mocked(prebuild).mockResolvedValue(undefined)],
        ['fails', () => vi.mocked(prebuild).mockRejectedValue(new Error('boom'))],
    ])('restores the working directory and logs nothing when the build %s', async (_label, mock) => {
        mock();
        const cwd = process.cwd();
        await checkBuild(argv);
        expect(process.chdir).toHaveBeenLastCalledWith(cwd);
        expect(addLog).not.toHaveBeenCalled();
    });
    it('throws when offline with no client', async () => {
        const fse = await import('fs-extra');
        vi.mocked(fse.pathExists).mockResolvedValueOnce(false);
        vi.mocked(isOnline).mockResolvedValue(false);
        await expect(checkBuild(argv)).rejects.toThrow('running mint validate after updating requires an internet connection.');
        expect(prebuild).not.toHaveBeenCalled();
    });
});
